const std=@import("std"); const KEY:u8=0xE9; const DIGITS="0123456789abcdef";
fn hv(c:u8)!u8{return switch(c){'0'...'9'=>c-'0','a'...'f'=>c-'a'+10,'A'...'F'=>c-'A'+10,else=>error.BadHex};}
pub fn main()!void{var inbuf:[1048576]u8=undefined;var rdr=std.io.getStdIn().reader();var out=std.io.getStdOut().writer();while(try rdr.readUntilDelimiterOrEof(&inbuf,'\n'))|raw|{var s=raw;if(s.len>0 and s[s.len-1]=='\r')s=s[0..s.len-1];if(std.mem.eql(u8,s,"PING")){try out.writeAll("PONG\n");continue;}if(std.mem.eql(u8,s,"QUIT"))break;if(s.len>=2 and (s[0]=='E' or s[0]=='D') and s[1]==' '){var i:usize=2;while(i+1<s.len): (i+=2){const v:u8=((try hv(s[i]))<<4)|(try hv(s[i+1]));const x:u8=v^KEY;try out.writeByte(DIGITS[x>>4]);try out.writeByte(DIGITS[x&15]);}try out.writeByte('\n');}else try out.writeAll("ERR\n");}}
